export interface Pending {
  /** What kind of work is in flight, for the label and for resuming it. */
  kind: "table" | "actions" | "obligation" | "move" | "counterTrigger" | "globalTrigger";
  label: string;
  tableId?: string;
  actions?: Action[];
  obligationId?: string;
  moveId?: string;
  trigger?: { counter: string; index: number; key: string };
